using MediatR;using Namaa.Application.Abstractions.Persistence;using Namaa.Application.Accounts.Dtos;using Namaa.Domain.Common.Errors;using Namaa.Domain.Common.Results;using Namaa.Domain.Entities;namespace Namaa.Application.Accounts.Commands.CreateAccount;public sealed class CreateAccountCommandHandler(IAccountRepository repository,IApplicationDbContext db):IRequestHandler<CreateAccountCommand,Result<AccountDto>>{public async Task<Result<AccountDto>>Handle(CreateAccountCommand request,CancellationToken cancellationToken){if(await repository.ExistsByAccountCodeAsync(request.AccountCode,cancellationToken))return Result.Failure<AccountDto>(AccountErrors.Duplicate);var e=Account.Create(request.AccountCode,request.AccountName,request.AccountType,request.IsPostingAllowed,request.Description,request.ParentAccountId);await repository.AddAsync(e,cancellationToken);await db.SaveChangesAsync(cancellationToken);return Result.Success(AccountDto.FromEntity(e));}}
